		echo '-c'
		echo ''
		cat "$AUDIT_FILE"
	} > "${AUDIT_FILE}.tmp"
	mv "${AUDIT_FILE}.tmp" "$AUDIT_FILE"
	chmod o-rwx $AUDIT_FILE
	chmod g-rwx $AUDIT_FILE
done

